<?php
$totalClasses=count($classes); $assignedTeachers=0; $totalSubjects=0;
foreach($classes as $class){if(trim((string)($class['teacher_reference']??''))!==''){$assignedTeachers++;}$totalSubjects+=(int)($class['subject_count']??0);}
$currency=(string)($institute['currency_symbol']??''); $unassigned=$totalClasses-$assignedTeachers;
?>
