lse: ?><span class="not-assigned"><i data-lucide="user-round-x"></i>Not assigned</span><?php endif; ?></td><td data-label="Subjects"><span class="subject-badge"><?= $count ?> <?= $count===1?'Subject':($count?'Subjects':'No subjects') ?></span></td><td class="class-actions-col" data-label="Actions"><div class="class-actions"><a class="class-action-button" href="<?= url('/admin/classes/'.$class['id'].'/edit') ?>" aria-label="Edit <?= e($name) ?>" title="Edit class"><i data-lucide="pencil"></i></a><form method="post" action="<?= url('/admin/classes/'.$class['id'].'/delete') ?>"><?= csrf_field() ?><button class="class-action-button class-action-button--danger" type="submit" aria-label="Delete <?= e($name) ?>" title="Delete class"><i data-lucide="trash-2"></i></button></form><form method="post" action="<?= url('/admin/classes/'.$class['id'].'/force-delete') ?>" data-force-single-form><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><button class="class-action-button class-action-button--force" type="button" data-force-single aria-label="Force delete <?= e($name) ?>" title="Force delete"><i data-lucide="flame"></i></button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></section>
